-- Nexa theme for Neovim / LazyVim
-- Auto-generated by Matugen. Do not edit manually.

local colors = {
  bg = "{{colors.background}}",
  fg = "{{colors.on_surface}}",
  surface = "{{colors.surface}}",
  surface_container = "{{colors.surface_container}}",
  surface_highest = "{{colors.surface_container_highest}}",
  primary = "{{colors.primary}}",
  on_primary = "{{colors.on_primary}}",
  primary_container = "{{colors.primary_container}}",
  on_primary_container = "{{colors.on_primary_container}}",
  secondary = "{{colors.secondary}}",
  tertiary = "{{colors.tertiary}}",
  error = "{{colors.error}}",
  outline = "{{colors.outline}}",
  outline_variant = "{{colors.outline_variant}}",
  muted = "{{colors.on_surface_variant}}",
}

vim.cmd("hi clear")
if vim.fn.exists("syntax_on") == 1 then
  vim.cmd("syntax reset")
end

vim.g.colors_name = "nexa"
vim.o.termguicolors = true

local hl = function(group, opts)
  vim.api.nvim_set_hl(0, group, opts)
end

-- Core UI
hl("Normal", { fg = colors.fg, bg = colors.bg })
hl("NormalFloat", { fg = colors.fg, bg = colors.surface_container })
hl("FloatBorder", { fg = colors.primary, bg = colors.surface_container })
hl("FloatTitle", { fg = colors.primary, bold = true })
hl("CursorLine", { bg = colors.surface_container })
hl("CursorLineNr", { fg = colors.primary, bold = true })
hl("LineNr", { fg = colors.outline })
hl("Pmenu", { fg = colors.fg, bg = colors.surface_container })
hl("PmenuSel", { fg = colors.on_primary, bg = colors.primary, bold = true })
hl("PmenuSbar", { bg = colors.surface_highest })
hl("PmenuThumb", { bg = colors.outline })
hl("StatusLine", { fg = colors.fg, bg = colors.surface_highest })
hl("StatusLineNC", { fg = colors.muted, bg = colors.surface_container })
hl("Visual", { bg = colors.primary_container, fg = colors.on_primary_container })
hl("Search", { fg = colors.on_primary, bg = colors.primary })
hl("IncSearch", { fg = colors.on_primary, bg = colors.secondary })
hl("Directory", { fg = colors.primary, bold = true })
hl("Title", { fg = colors.primary, bold = true })
hl("VertSplit", { fg = colors.outline_variant })
hl("WinSeparator", { fg = colors.outline_variant })

-- Standard Syntax
hl("Comment", { fg = colors.muted, italic = true })
hl("Constant", { fg = colors.secondary })
hl("String", { fg = colors.secondary })
hl("Character", { fg = colors.secondary })
hl("Number", { fg = colors.tertiary })
hl("Boolean", { fg = colors.tertiary, bold = true })
hl("Float", { fg = colors.tertiary })
hl("Identifier", { fg = colors.fg })
hl("Function", { fg = colors.primary, bold = true })
hl("Statement", { fg = colors.primary })
hl("Conditional", { fg = colors.primary, bold = true })
hl("Repeat", { fg = colors.primary, bold = true })
hl("Label", { fg = colors.primary })
hl("Operator", { fg = colors.outline })
hl("Keyword", { fg = colors.primary, bold = true })
hl("Exception", { fg = colors.error, bold = true })
hl("PreProc", { fg = colors.tertiary })
hl("Include", { fg = colors.primary })
hl("Define", { fg = colors.primary })
hl("Macro", { fg = colors.tertiary })
hl("Type", { fg = colors.secondary, bold = true })
hl("StorageClass", { fg = colors.primary })
hl("Structure", { fg = colors.primary })
hl("Special", { fg = colors.tertiary })
hl("Underlined", { underline = true })
hl("Error", { fg = colors.error, bold = true })
hl("Todo", { fg = colors.primary, bold = true })

-- Treesitter Highlighting
hl("@comment", { link = "Comment" })
hl("@string", { link = "String" })
hl("@number", { link = "Number" })
hl("@boolean", { link = "Boolean" })
hl("@function", { link = "Function" })
hl("@function.builtin", { fg = colors.primary, italic = true })
hl("@function.call", { fg = colors.primary })
hl("@keyword", { link = "Keyword" })
hl("@keyword.function", { fg = colors.primary, bold = true })
hl("@keyword.return", { fg = colors.primary, bold = true })
hl("@keyword.operator", { fg = colors.outline })
hl("@type", { link = "Type" })
hl("@type.builtin", { fg = colors.secondary, italic = true })
hl("@variable", { fg = colors.fg })
hl("@variable.builtin", { fg = colors.tertiary })
hl("@variable.parameter", { fg = colors.fg, italic = true })
hl("@constant", { link = "Constant" })
hl("@constant.builtin", { fg = colors.secondary, bold = true })
hl("@property", { fg = colors.fg })
hl("@field", { fg = colors.fg })
hl("@punctuation.bracket", { fg = colors.outline })
hl("@punctuation.delimiter", { fg = colors.outline })

-- Diagnostics (LSP)
hl("DiagnosticError", { fg = colors.error })
hl("DiagnosticWarn", { fg = colors.tertiary })
hl("DiagnosticInfo", { fg = colors.secondary })
hl("DiagnosticHint", { fg = colors.primary })
hl("DiagnosticUnderlineError", { undercurl = true, sp = colors.error })
hl("DiagnosticUnderlineWarn", { undercurl = true, sp = colors.tertiary })

-- Git
hl("GitSignsAdd", { fg = colors.secondary })
hl("GitSignsChange", { fg = colors.tertiary })
hl("GitSignsDelete", { fg = colors.error })

-- Telescope & Snacks Pickers
hl("TelescopeBorder", { fg = colors.primary, bg = colors.surface_container })
hl("TelescopePromptBorder", { fg = colors.primary, bg = colors.surface_container })
hl("TelescopePromptNormal", { fg = colors.fg, bg = colors.surface_container })
hl("TelescopeResultsNormal", { fg = colors.fg, bg = colors.surface })
hl("TelescopeSelection", { bg = colors.primary_container, fg = colors.on_primary_container })
hl("TelescopeMatching", { fg = colors.primary, bold = true })

return colors
